import {hearButton} from './play-media.mjs';
import {learningInvitations} from './learning-invitations.mjs';
import {starterIngredients} from './cafe-content.mjs';
import {livingVisit,hasLivingRecord} from './living-core.mjs';
import {spiralAnimals,spiralAnimal,spiralReasons,spiralCase,spiralPlaces,spiralTarget,spiralMatch} from './living-spiral-content.mjs';
import {hasSpiral,spiralState,currentSpiral,spiralReady,spiralClosed,setSpiralOption,startSpiral,selectSpiralPlace,inspectSpiral,chooseSpiral,compareSpiral,supportSpiral,findSpiral,inputSpiral,submitSpiralCount,helpSpiralCount,carrySpiral,leaveSpiral} from './living-spiral-core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const food=id=>starterIngredients.find(a=>a.id===id);
const button=(attr,text,cls='secondary',disabled=false)=>`<button type="button" class="${cls}" ${attr} ${disabled?'disabled':''}>${text}</button>`;
const hear=(text,label)=>hearButton(text,label).replace('data-speak=','data-spiral-audio data-speak=');
const total=r=>r.task.packs*r.task.bites;
export function spiralAnimalArt(id){
 let art,alt;
 if(id==='snail'){
  alt='Original illustration of a garden land snail, with a spiral shell and feelers.';
  art='<path d="M35 128Q78 101 133 123l27-14v24H33Z" fill="#aeba98" stroke="#52675e" stroke-width="3"/><circle cx="94" cy="92" r="34" fill="#d6b77d" stroke="#75593c" stroke-width="3"/><path d="M77 103q-19-26 9-35 28-6 26 20-2 20-21 11-9-6 1-12" fill="none" stroke="#75593c" stroke-width="4"/><path d="M147 115l-3-32m12 28 15-28" stroke="#52675e" stroke-width="3"/><circle cx="144" cy="81" r="4" fill="#183f39"/><circle cx="172" cy="81" r="4" fill="#183f39"/>';
 }else if(id==='woodlouse'){
  alt='Original illustration of a woodlouse, with a segmented oval body and seven pairs of legs.';
  art=Array.from({length:7},(_,i)=>`<path d="M${65+i*12} 83l-7-15m7 45-7 15" stroke="#52675e" stroke-width="3"/>`).join('')+'<ellipse cx="103" cy="98" rx="49" ry="25" fill="#a4afa5" stroke="#52675e" stroke-width="3"/>'+Array.from({length:6},(_,i)=>`<path d="M${71+i*12} 77q-8 21 0 42" fill="none" stroke="#52675e" stroke-width="2"/>`).join('')+'<path d="M148 91l19-17m-17 28 21 7" fill="none" stroke="#52675e" stroke-width="3"/><circle cx="144" cy="91" r="3" fill="#183f39"/>';
 }else{
  alt='Original illustration of an adult butterfly, with four wings and six legs.';
  art='<path d="M106 89Q39 25 28 79Q25 114 98 102Q40 124 65 147Q96 155 107 107M113 89Q180 25 191 79Q194 114 121 102Q179 124 154 147Q123 155 112 107" fill="#e9b84a" stroke="#9b763f" stroke-width="3"/><path d="M109 77V125m0-45-10-18m12 18 10-18" stroke="#52675e" stroke-width="6" stroke-linecap="round"/>'+[90,102,114].map(y=>`<path d="M108 ${y}l-17 8m20-8 17 8" stroke="#52675e" stroke-width="2"/>`).join('')+'<circle cx="64" cy="83" r="11" fill="#da8d8d"/><circle cx="155" cy="83" r="11" fill="#da8d8d"/>';
 }
 return `<svg class="spiral-animal-art" viewBox="0 0 220 165" role="img" aria-label="${alt}">${art}</svg>`;
}
const leaves='<path d="M75 144q-31-29-42-4 12 25 42 4m18 10q31-29 42-4-12 25-42 4m48-14q27-22 35-2-12 21-35 2" fill="#8f9c62" stroke="#627a51" stroke-width="2"/>';
export function spiralPlaceArt(p,revealed=false){
 const shaded=revealed&&p.cover,wet=revealed&&p.damp;
 let art='<path d="M8 142Q100 115 232 143V180H8Z" fill="#c9d2b5"/>';
 if(p.kind==='log')art+='<path d="M28 59Q100 43 181 66V108Q99 91 28 108Z" fill="#866544" stroke="#624d36" stroke-width="3"/><ellipse cx="181" cy="87" rx="21" ry="24" fill="#d6b77d" stroke="#624d36" stroke-width="3"/>'+(revealed&&!p.cover?'<path d="M42 65l25 16-16 11m16-11 24-3" fill="none" stroke="#e9b84a" stroke-width="4"/>':'');
 else if(p.kind==='stone')art+='<path d="M29 104Q22 55 94 63Q171 30 205 99L196 118H39Z" fill="#aab1a2" stroke="#6f8073" stroke-width="3"/>';
 else if(p.kind==='pot')art+='<path d="M61 51H157L171 121H46Z" fill="#ce9275" stroke="#966d50" stroke-width="3"/><path d="M45 120H172v12H45Z" fill="#d6b77d" stroke="#966d50" stroke-width="3"/>';
 else if(p.kind==='pond')art='<path d="M8 52Q65 38 118 52T232 52V180H8Z" fill="#abc4da"/><path d="M8 52Q65 38 118 52T232 52" fill="none" stroke="#397958" stroke-width="3"/><path d="M76 174q-12-41 9-70m-8 47q-24-4-21-24 23 0 21 24" fill="#8aa887" stroke="#397958" stroke-width="3"/>';
 else if(p.kind==='leaves')art+=leaves+leaves.replaceAll('144','117').replaceAll('154','126').replaceAll('140','115');
 else{
  if(p.kind==='flowerpot')art+='<path d="M45 131H185L169 174H60Z" fill="#ce9275" stroke="#966d50" stroke-width="3"/>';
  if(p.kind==='hedge')art+='<path d="M13 125V57Q41 20 67 58Q94 14 125 52Q164 9 199 52L228 63V126Z" fill="#8f9c62"/>';
  art+=[55,112,170].map((x,i)=>`<path d="M${x} 148V${70+i%2*16}" stroke="#397958" stroke-width="4"/>${p.kind==='buds'?`<ellipse cx="${x}" cy="${65+i%2*16}" rx="8" ry="15" fill="#b8c5a4" stroke="#397958" stroke-width="2"/>`:`<g transform="translate(${x} ${65+i%2*16})"><circle cx="-10" r="10" fill="#da8d8d"/><circle cx="10" r="10" fill="#da8d8d"/><circle cy="-10" r="10" fill="#da8d8d"/><circle cy="10" r="10" fill="#da8d8d"/><circle r="6" fill="#e9b84a"/></g>`}`).join('');
 }
 if(shaded)art+='<path d="M35 123Q110 104 195 123V170H35Z" fill="#52675e" opacity=".3"/>';
 if(wet)art+=leaves+'<path d="M82 121q-10 15 0 15t0-15m55 5q-10 15 0 15t0-15" fill="#729fa4"/>';
 if(revealed&&p.nectar)art+='<rect x="46" y="150" width="150" height="24" rx="5" fill="#fff8e4"/><text x="121" y="167" text-anchor="middle" font-size="13" fill="#183f39">Nectar-bearing flowers</text>';
 if(revealed&&!p.damp&&!p.nectar&&p.kind!=='pond')art+='<circle cx="210" cy="28" r="18" fill="#e9b84a"/><path d="M160 151l10 9-5 11m5-11 16-2" fill="none" stroke="#a37f50" stroke-width="2"/>';
 return `<svg class="spiral-place-art" viewBox="0 0 240 185" role="img" aria-label="${esc(revealed?p.observation:p.name+'. Inspect its pictured conditions.')} "><rect x="4" y="4" width="232" height="177" rx="18" fill="#eef2e6"/>${art}</svg>`;
}
function options(state){
 const s=spiralState(state),o=s?.options||{animal:'mix',range:'small',ingredient:'needed'};
 return `<details class="spiral-settings panel"><summary>Choose our next trail</summary><p>These choices change the next search. Your waiting animal and parcel stay the same.</p><div class="spiral-setting-grid"><label>Animal<select data-spiral-option="animal">${[['mix','A mix of neighbors'],...spiralAnimals.map(a=>[a.id,a.name])].map(([id,label])=>`<option value="${id}" ${o.animal===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Parcel numbers<select data-spiral-option="range"><option value="small" ${o.range==='small'?'selected':''}>Small packs · 2 to 5 packs of 2 to 5</option><option value="all" ${o.range==='all'?'selected':''}>All facts · 1 × 1 up to 12 × 12</option></select></label><label>Find food for<select data-spiral-option="ingredient"><option value="needed" ${o.ingredient==='needed'?'selected':''}>Our waiting table or a low jar</option>${starterIngredients.map(a=>`<option value="${a.id}" ${o.ingredient===a.id?'selected':''}>${a.name}</option>`).join('')}</select></label></div></details>`;
}
function habitat(r){
 const c=spiralCase(r.task.caseId),a=spiralAnimal(c.animal),places=spiralPlaces(r.task),last=r.attempts.at(-1);
 const feedback=!last?'Choose a place and the clues that make it useful.':spiralMatch(r.task,last)?'Those clues fit this animal’s current need.':`Look again at ${places[last.place].name.toLowerCase()}. ${places[last.place].observation} Which place and reason match this animal’s need?`;
 return `<section class="spiral-need"><div>${spiralAnimalArt(a.id)}</div><div><p class="place-name">${a.name} · ${r.task.familiar?'A place you know, with a new parcel':'A new place to explore'}</p><h2>${a.need}</h2><p>${esc(c.note)}</p>${hear(`${a.name}. ${a.need} Delivery note: ${c.note}`,'Hear the animal and note')}${button('data-spiral-support="vocabulary"',`What does “${a.word}” mean?`,'text-button')}${r.vocabulary?`<p class="hint">${a.definition}</p>`:''}</div></section><div class="spiral-place-grid">${places.map((p,i)=>`<article class="spiral-place" aria-labelledby="spiral-place-${i}"><h3 id="spiral-place-${i}">${p.name}</h3>${spiralPlaceArt(p,r.inspected.includes(i))}${button(`data-spiral-inspect="${i}"`,r.inspected.includes(i)?'Look again':'Look closely','primary')}<div id="spiral-clue-${i}" tabindex="-1">${r.inspected.includes(i)?`<p>${p.observation}</p>${hear(p.observation,'Hear this clue')}`:'<p class="tiny">Look closely to see what this place is like.</p>'}</div></article>`).join('')}</div><details class="living-notebook"><summary>Picture-clue notebook (${r.inspected.length} places)</summary><ul>${r.inspected.map(i=>`<li><strong>${places[i].name}:</strong> ${places[i].observation}</li>`).join('')}</ul></details><section class="living-comparison"><h2>Which place fits this need?</h2><fieldset><legend>Choose a place</legend><div class="living-options">${places.map((p,i)=>button(`data-spiral-place-answer="${i}" aria-pressed="${r.answerPlace===i}"`,p.name,r.answerPlace===i?'secondary selected':'secondary')).join('')}</div></fieldset><fieldset><legend>Choose a reason</legend><div class="living-options">${spiralReasons.map(x=>button(`data-spiral-reason="${x.id}" aria-pressed="${r.answerReason===x.id}"`,x.label,r.answerReason===x.id?'secondary selected':'secondary')).join('')}</div></fieldset>${button('data-spiral-compare','Compare our clues','primary',r.answerPlace===null||!r.answerReason)}<p class="spiral-feedback" role="status">${esc(feedback)}</p>${button('data-spiral-support="explained"','Work it out together')}${r.explained?`<div class="hint"><p>${a.why} Picture clue: ${places[spiralTarget(r.task)].observation}</p>${hear(a.why+' '+places[spiralTarget(r.task)].observation,'Hear our explanation')}</div>`:''}</section><section class="living-search"><h2>Follow the delivery note</h2>${spiralReady(r)?button('data-spiral-find',`Look beside ${places[spiralTarget(r.task)].name.toLowerCase().replace(/^the /,'the ')}`,'primary'):`<p>${!r.inspected.includes(spiralTarget(r.task))?'Look closely at the place that fits the animal’s need. ':''}${r.inspected.length<2?'Compare at least two places. ':''}${!r.matched&&!r.explained?'Try a place and reason, or think it through together.':''}</p>`}</section>`;
}
function packs(r){return `<div class="spiral-packs" role="img" aria-label="${r.task.packs} sealed packs, each containing ${r.task.bites} bites of ${food(r.task.ingredientId).name}">${Array.from({length:r.task.packs},(_,i)=>`<figure class="spiral-pack"><div aria-hidden="true">${Array.from({length:r.task.bites},()=>'<i></i>').join('')}</div><figcaption>Pack ${i+1}<br>${r.task.bites} bites</figcaption></figure>`).join('')}</div>`;}
function parcel(r,state){
 const c=spiralCase(r.task.caseId),a=spiralAnimal(c.animal),p=spiralPlaces(r.task)[spiralTarget(r.task)],n=state.cafe?.stock?.[r.task.ingredientId];
 const full=!Number.isSafeInteger(n)||n+total(r)>180,answered=r.mathMatched||r.mathHelp,last=r.mathAttempts.at(-1);
 return `<section class="living-parcel"><h2 id="spiral-parcel-title" tabindex="-1">A neighbor stays. A parcel travels.</h2><div class="spiral-found-scene">${spiralAnimalArt(a.id)}${spiralPlaceArt(p,true)}</div><p>In our story, the ${a.id==='butterfly'?'adult butterfly':a.id==='woodlouse'?'woodlouse':'land snail'} is near ${p.name.toLowerCase()}. We leave the animal and its place alone. The sealed café food is a separate delivery.</p><p class="tiny">In a real garden, an animal might rest somewhere else. This parcel is pretend café food, just for the café.</p><h3>${food(r.task.ingredientId).name} for our neighbors</h3>${packs(r)}<p>${r.task.packs} packs × ${r.task.bites} bites in each. How many bites altogether?</p>${hear(`${r.task.packs} packs of ${food(r.task.ingredientId).name}, with ${r.task.bites} bites in each pack. How many bites altogether?`,'Hear the parcel question')}<form id="spiral-count-form"><label for="spiral-count">Our count</label><div class="spiral-count-row"><input id="spiral-count" inputmode="numeric" autocomplete="off" maxlength="20" value="${esc(r.input)}"><button type="submit" class="primary">Check my count</button></div></form><p class="spiral-number-feedback" role="status">${last?(last.value===total(r)?'That count fits the equal packs.':'Let’s count each pack, connect a known fact, or count with Moss.'):'Try a count, or count with Moss.'}</p>${button('data-spiral-count-help','Count with Moss')}${r.mathHelp?`<div class="hint"><p>${Array.from({length:r.task.packs},(_,i)=>(i+1)*r.task.bites).join(', ')}. Altogether: ${r.task.packs} × ${r.task.bites} = ${total(r)} bites.</p>${hear(`${r.task.packs} packs of ${r.task.bites} make ${total(r)} bites.`,'Hear the count')}</div>`:''}<div class="spiral-carry">${button('data-spiral-carry',answered?`Carry ${total(r)} bites to the café`:'Carry the parcel to the café','primary',!answered||full)}${full?'<p role="status">The jar holds 180 bites. This parcel will wait while you use some at the café. Or leave it behind and try another search.</p>':!answered?'<p>Check a count or count with Moss before carrying. Help is always welcome.</p>':''}<a class="secondary" href="#cafe">Visit the waiting café</a></div><details class="living-plan"><summary>A question to take into the next visit</summary><p>${c.wonder}</p><p>${a.planning}</p><a href="#wonder/many-rectangles">Return to the planting plan</a></details></section>`;
}
function closed(r){const c=spiralCase(r.task.caseId),a=spiralAnimal(c.animal);return `<section class="living-parcel spiral-ending">${spiralAnimalArt(a.id)}<h2 id="spiral-ending-title" tabindex="-1">${r.carried?'A delivery for our neighbors.':'A trail kept in our notebook.'}</h2><p>${r.carried?`${total(r)} ${food(r.task.ingredientId).name} bites were carried to the café. This visit cannot supply them again.`:'This parcel was left behind. No food was added.'}</p><p>${c.wonder}</p><p>${a.planning}</p><div class="summary-links">${button('data-spiral-start','Another search','primary')}<a class="secondary" href="#cafe">Visit the café</a><a class="secondary" href="#wonder/many-rectangles">Return to the planting plan</a><a class="text-button" href="#living">Choose a different trail</a></div></section>`;}
function parentInfo(){return `<details class="panel"><summary>Grown-ups: a spiral of ideas</summary><p>Nine authored settings revisit damp shelter with land snails and woodlice, then contrast shelter with nectar for an adult butterfly. Conditions and positions change; an object's name is not its suitability. Short notes connect words to pictured clues. Parcel math has separate attempts/help; small packs cycle all 16 ordered 2–5 pairs, and all-facts mode cycles all 144 ordered facts through 12×12. Counts and ingredient choices are frozen for each visit. Settings affect the next visit only.</p><p>Pictures are supplied clues, not field measurements. Familiar cases are labeled; new ecology is not generated. A parcel left behind adds no food and keeps no waiting stock claim. These are guided picture investigations, not field observations, independent reading tests or mastery/placement evidence. Pictures, vocabulary, explanation and narration support remain distinct in notes. A parcel's displayed math is registered as a prior fact exposure elsewhere in the app. No learner data leaves this browser.</p><p>Science references: <a href="https://www.nhm.ac.uk/take-part/monitor-and-encourage-nature/project-archive/slime-search.html" target="_blank" rel="noopener">NHM land-snail habitats</a>, <a href="https://www.rhs.org.uk/biodiversity/woodlice" target="_blank" rel="noopener">RHS woodlice</a>, <a href="https://www.rhs.org.uk/wildlife/butterflies-in-your-garden" target="_blank" rel="noopener">RHS butterflies and caterpillars</a>. These pictured comparisons address parts of Marble’s habitat/needs/vocabulary topics, not field identification, food chains or full topic coverage.</p></details>`;}
export function spiralPage(state,slug){
 const s=spiralState(state),r=s?.current,bad=hasSpiral(state)&&!s;
 const intro='Come back to the Living Garden. Look closely, compare clues, and find a sealed café parcel. Different neighbors need different things. The same place can change, too. Choose a trail or keep going with your waiting visit.';
 const header=`<header class="page-heading"><a class="back" href="#numbers"><span aria-hidden="true">←</span> Moss’s planning table</a><p class="place-name">Living Garden · Follow another curiosity</p><h1>Same garden.<br>New things to notice.</h1><p>Look closely. Follow a clue. Find something for our neighbors.</p>${r&&!spiralClosed(r)?hear(intro,'Hear our garden invitation'):hearButton(intro,'Hear our garden invitation')}</header>`;
 if(bad)return `<div class="living-page">${header}<section class="panel"><h2>An earlier exploration is kept</h2><p>This saved format cannot be played here. Your exact work remains in the notes download. No replacement parcel will be issued.</p><a href="#notes">Open grown-up notes</a></section><a href="#living/first">Visit the original snail investigation</a>${learningInvitations('living')}</div>`;
 let content;
 if(slug==='visit'&&r){content=`<p class="place-name">Visit ${r.id+1} · ${spiralCase(r.task.caseId).title}</p>${spiralClosed(r)?closed(r):`${r.found?parcel(r,state):habitat(r)}<div class="spiral-pause"><a href="#living">Take a break and choose a trail</a>${button('data-spiral-leave','Leave this parcel behind and try another search','text-button')}<p class="tiny">Leaving closes this visit without adding food. Its notes stay. The next search gets its own parcel.</p></div>`}${options(state)}`;}
 else content=`<aside class="food-hub-entry body-hub-entry"><a class="secondary" href="#living/food">Food links: who gets food from whom?</a><p class="tiny">Two feeding links. Read the arrow from food to eater. Then change a trail if you like.</p></aside><aside class="food-hub-entry body-hub-entry"><a class="secondary" href="#living/fork">Build a food-link fork</a><p class="tiny">Four named cards. Make two paths through one aphid, then read a closer source and revise an arrow.</p></aside><aside class="life-hub-entry body-hub-entry"><a class="secondary" href="#living/stages">One butterfly: connect its life stages</a><p class="tiny">Four pictured stages, one possible life story and the beginning of offspring.</p></aside><aside class="body-hub-entry"><a class="secondary" href="#living/bodies">Body clues: follow a picture key</a><p class="tiny">Look closely at four adult diagrams. Use body clues to find each animal’s name.</p></aside><section class="spiral-welcome"><h2>Who shall we look for?</h2><div class="spiral-animal-grid">${spiralAnimals.map(a=>`<article>${spiralAnimalArt(a.id)}<h3>${a.name}</h3><p>${a.need}</p>${button(`data-spiral-animal-start="${a.id}"`,`Follow the ${a.id==='butterfly'?'butterfly':a.id==='woodlouse'?'woodlouse':'snail'}`,'secondary',!!r&&!spiralClosed(r))}</article>`).join('')}</div>${r&&!spiralClosed(r)?`<a class="primary" href="#living/visit">Continue our waiting ${spiralAnimal(spiralCase(r.task.caseId).animal).name.toLowerCase()} visit</a><p>Its clues, count and parcel are waiting. Finish it or leave it behind before starting another.</p>`:button('data-spiral-start','Start our next trail','primary')}<p class="tiny">Three animals. Nine pictured settings to revisit. Each later search brings another parcel and new numbers.</p></section>${options(state)}<aside class="living-invitation"><h2>Our first small shelter</h2><p>${hasLivingRecord(state)?livingVisit(state)?.carried?'Your original parcel has already been carried. Its visit and notes are still here.':'Your original snail investigation stays exactly as you left it.':'The first snail investigation is still open, with its own one-time parcel.'}</p><a class="secondary" href="#living/first">${hasLivingRecord(state)?'Return to our original visit':'Try the original snail visit'}</a></aside>`;
 return `<div class="living-page spiral-page">${header}${content}${parentInfo()}${learningInvitations('living')}</div>`;
}
export function spiralNotes(state){
 if(!hasSpiral(state))return '';const s=spiralState(state);
 if(!s)return `<details class="panel"><summary>Kept Living Garden exploration</summary><p>Unsupported record; retained without a replacement.</p><pre>${esc(JSON.stringify(state.livingExploration,null,2))}</pre></details>`;
 const rounds=[...s.history,...(s.current?[s.current]:[])].filter(r=>r.revision==='habitat-round-1');
 return `<details class="panel"><summary>Living Garden changing visits (${rounds.length} retained)</summary><p>Latest 24 closed visits plus the current one. Supplied pictures and familiar settings; no independent habitat, reading or recall certification.</p>${rounds.map(r=>{const c=spiralCase(r.task.caseId),ps=spiralPlaces(r.task);return `<section><h3>Visit ${r.id+1}: ${c.title} · ${spiralAnimal(c.animal).name}</h3><p>${r.task.familiar?'Setting previously offered':'First offer of setting'}. Picture clues viewed: ${r.inspected.map(i=>esc(ps[i].name)).join(', ')||'none'}.</p><p>Place/reason attempts: ${r.attempts.map(a=>`${esc(ps[a.place].name)} + ${esc(spiralReasons.find(x=>x.id===a.reason).label)}${a.afterHelp?' (after explanation)':''}${a.afterVocabulary?' (after vocabulary)':''}`).join('; ')||'none'}.</p><p>Explanation: ${r.explained?'yes':'no'}. Vocabulary: ${r.vocabulary?'yes':'no'}. Audio requested: ${r.audioRequested?'yes':'no'}; playback unobserved.</p><p>Parcel: ${r.task.packs} × ${r.task.bites} ${food(r.task.ingredientId).name} bites. Input: ${esc(r.input)}. Counts tried: ${r.mathAttempts.map(a=>`${a.value}${a.afterHelp?' (with help)':''}`).join(', ')||'none'}. Count explanation: ${r.mathHelp?'yes':'no'}.</p><p>${r.carried?`Carried ${total(r)} bites once`:r.left?'Left without supplies':r.found?'Found, still waiting':'Still searching'}.</p></section>`;}).join('')}</details>`;
}
export function bindSpiral(state,{save,render,navigate,focus,startVisit=startSpiral}){
 const bind=(selector,act,target)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(act(b)){save();render();if(target)focus?.(typeof target==='function'?target(b):target);}}));
 const start=()=>{if(startVisit(state)){save();navigate('#living/visit');}};
 document.querySelectorAll('[data-spiral-start]').forEach(b=>b.addEventListener('click',start));
 document.querySelectorAll('[data-spiral-animal-start]').forEach(b=>b.addEventListener('click',()=>{if(setSpiralOption(state,'animal',b.dataset.spiralAnimalStart))start();}));
 document.querySelectorAll('[data-spiral-option]').forEach(el=>el.addEventListener('change',()=>{if(setSpiralOption(state,el.dataset.spiralOption,el.value))save();}));
 bind('[data-spiral-inspect]',b=>selectSpiralPlace(state,Number(b.dataset.spiralInspect))&&inspectSpiral(state),b=>`#spiral-clue-${b.dataset.spiralInspect}`);
 bind('[data-spiral-place-answer]',b=>chooseSpiral(state,'answerPlace',Number(b.dataset.spiralPlaceAnswer)),b=>`[data-spiral-place-answer="${b.dataset.spiralPlaceAnswer}"]`);
 bind('[data-spiral-reason]',b=>chooseSpiral(state,'answerReason',b.dataset.spiralReason),b=>`[data-spiral-reason="${b.dataset.spiralReason}"]`);
 bind('[data-spiral-compare]',()=>compareSpiral(state),'.spiral-feedback');
 bind('[data-spiral-support]',b=>supportSpiral(state,b.dataset.spiralSupport),b=>b.dataset.spiralSupport==='vocabulary'?'.spiral-need .hint':'.living-comparison .hint');
 bind('[data-spiral-find]',()=>findSpiral(state),'#spiral-parcel-title');
 document.querySelector('#spiral-count')?.addEventListener('input',e=>{if(inputSpiral(state,e.target.value))save();});
 document.querySelector('#spiral-count-form')?.addEventListener('submit',e=>{e.preventDefault();if(submitSpiralCount(state)){save();render();}else{const message=document.querySelector('.spiral-number-feedback');if(message)message.textContent='Try a whole number from 0 to 999, or count with Moss.';}focus?.('.spiral-number-feedback');});
 bind('[data-spiral-count-help]',()=>helpSpiralCount(state),'.living-parcel .hint');
 bind('[data-spiral-carry]',()=>carrySpiral(state),'#spiral-ending-title');
 document.querySelectorAll('[data-spiral-leave]').forEach(b=>b.addEventListener('click',()=>{if(leaveSpiral(state)){save();navigate('#living');}}));
 document.querySelectorAll('[data-spiral-audio]').forEach(b=>b.addEventListener('click',()=>{if(supportSpiral(state,'audioRequested'))save();}));
}
